        <li><?php echo esc_html(__("BotFather restituisce il link del nuovo bot e un", 'ws40-broadcaster')); ?> <strong><?php echo esc_html(__("token API", 'ws40-broadcaster')); ?></strong><?php echo esc_html(__(". Copia il token: dovrai inserirlo nelle impostazioni del plugin.", 'ws40-broadcaster')); ?></li></ol>
        <p class="cmt-note"><?php echo esc_html(__("Nome, username e token sono tre cose diverse. Il token va nel campo «Token BotFather»; nel campo «Canale» va invece la destinazione dei messaggi, non lo username del bot.", 'ws40-broadcaster')); ?></p>
